  1  #!/usr/bin/env node
  2  "use strict";
  3  
  4  const fs = require("node:fs");
  5  const vm = require("node:vm");
  6  
  7  const MAX_SKETCH_BYTES = 100_000;
  8  const VM_TIMEOUT_MS = 100;
  9  const DRAW_FRAMES = 5;
 10  const MAX_ERROR_CHARS = 500;
 11  const MAX_CONSOLE_CHARS = 2_000;
 12  
 13  class PolicyError extends Error {
 14    constructor(message) {
 15      super(message);
 16      this.name = "PolicyError";
 17    }
 18  }
 19  
 20  function bounded(value, limit = MAX_ERROR_CHARS) {
 21    return String(value ?? "Unknown error").replace(/[\r\n\t]+/g, " ").replace(/\s+/g, " ").slice(0, limit);
 22  }
 23  
 24  function fail(code, error) {
 25    const name = bounded(error && error.name ? error.name : "Error", 80);
 26    const message = bounded(error && error.message ? error.message : error);
 27    process.stderr.write(`P5CHECK FAIL ${name}: ${message}\n`);
 28    process.exit(code);
 29  }
 30  
 31  function validateInput() {
 32    if (process.argv.length !== 3 || process.argv[2] !== "sketch.js") {
 33      throw Object.assign(new Error("usage: node p5check.js sketch.js"), { exitCode: 2 });
 34    }
 35    let stat;
 36    try {
 37      stat = fs.lstatSync("sketch.js");
 38    } catch (error) {
 39      throw new PolicyError(`sketch.js is missing: ${bounded(error.message)}`);
 40    }
 41    if (!stat.isFile()) {
 42      throw new PolicyError("sketch.js must be a regular file");
 43    }
 44    if (stat.size === 0) {
 45      throw new PolicyError("sketch.js must not be empty");
 46    }
 47    if (stat.size > MAX_SKETCH_BYTES) {
 48      throw new PolicyError(`sketch.js exceeds ${MAX_SKETCH_BYTES} bytes`);
 49    }
 50    return fs.readFileSync("sketch.js", "utf8");
 51  }
 52  
 53  const unsupportedP5 = [
 54    "loadImage", "loadJSON", "loadStrings", "loadTable", "loadXML", "loadBytes", "httpGet",
 55    "httpPost", "httpDo", "loadSound", "createAudio", "createVideo", "createCapture", "createElement",
 56    "createDiv", "createP", "createSpan", "createImg", "createA", "createSlider", "createButton",
 57    "createCheckbox", "createSelect", "createInput", "createFileInput", "createGraphics", "WEBGL",
 58    "WEBGPU", "shader", "loadShader", "createShader", "save", "saveCanvas", "saveFrames"
 59  ];
 60  
 61  const forbiddenIdentifiers = [
 62    "require", "module", "exports", "process", "Buffer", "fetch", "XMLHttpRequest", "WebSocket",
 63    "EventSource", "localStorage", "sessionStorage", "indexedDB", "document", "window", "location",
 64    "navigator", "Worker", "SharedWorker", "ServiceWorker", "WebAssembly", "global", "globalThis",
 65    "Deno", "Bun"
 66  ];
 67  
 68  function rejectForbiddenSurface(source) {
 69    for (const name of unsupportedP5) {
 70      if (new RegExp(`\\b${name}\\b`).test(source)) {
 71        throw new PolicyError(`Unsupported p5 API: ${name}`);
 72      }
 73    }
 74    for (const name of forbiddenIdentifiers) {
 75      if (new RegExp(`\\b${name}\\b`).test(source)) {
 76        throw new PolicyError(`Forbidden identifier: ${name}`);
 77      }
 78    }
 79    const dynamicPatterns = [
 80      [/\bimport\s*\(/, "dynamic import"],
 81      [/\beval\s*\(/, "eval"],
 82      [/\b(?:AsyncFunction|GeneratorFunction|Function)\s*\(/, "dynamic Function"],
 83      [/\bconstructor\b/, "constructor access"],
 84      [/\bprototype\b|__proto__/, "prototype access"],
 85      [/\b(?:getPrototypeOf|setPrototypeOf|defineProperty|defineProperties)\b/, "prototype mutation"],
 86      [/\b(?:Proxy|Reflect)\b/, "metaprogramming"]
 87    ];
 88    for (const [pattern, label] of dynamicPatterns) {
 89      if (pattern.test(source)) {
 90        throw new PolicyError(`Forbidden dynamic-code construct: ${label}`);
 91      }
 92    }
 93  }
 94  
 95  function number(value, fallback = 0) {
 96    const converted = Number(value);
 97    return Number.isFinite(converted) ? converted : fallback;
 98  }
